PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE OrderItems(OrderId INTEGER NOT NULL REFERENCES Orders(Id) ON DELETE CASCADE, ProductId INTEGER NOT NULL REFERENCES Products(Id) ON DELETE RESTRICT, Quantity INTEGER NOT NULL CHECK(Quantity > 0), UnitPriceCents INTEGER NOT NULL CHECK(UnitPriceCents >= 0), PRIMARY KEY(OrderId,ProductId));
CREATE TABLE OrderStatuses(Id INTEGER PRIMARY KEY, Name TEXT NOT NULL UNIQUE);
CREATE TABLE Orders(Id INTEGER PRIMARY KEY, UserId INTEGER NOT NULL REFERENCES Users(Id), Address TEXT NOT NULL CHECK(length(trim(Address)) > 0), StatusId INTEGER NOT NULL REFERENCES OrderStatuses(Id), CreatedAt TEXT NOT NULL, DeliveryAt TEXT);
CREATE TABLE ProductTypes(Id INTEGER PRIMARY KEY, Name TEXT NOT NULL UNIQUE);
CREATE TABLE Products(Id INTEGER PRIMARY KEY, Name TEXT NOT NULL, TypeId INTEGER NOT NULL REFERENCES ProductTypes(Id), Description TEXT NOT NULL, Composition TEXT NOT NULL, PriceCents INTEGER NOT NULL CHECK(PriceCents >= 0), Discount INTEGER NOT NULL CHECK(Discount BETWEEN 0 AND 100), DiscountActive INTEGER NOT NULL CHECK(DiscountActive IN (0,1)), MinStock INTEGER NOT NULL CHECK(MinStock >= 0), Stock INTEGER NOT NULL CHECK(Stock >= 0), ImagePath TEXT NOT NULL DEFAULT '');
CREATE TABLE Roles(Id INTEGER PRIMARY KEY, Name TEXT NOT NULL UNIQUE);
CREATE TABLE Users(Id INTEGER PRIMARY KEY, FullName TEXT NOT NULL, Login TEXT NOT NULL UNIQUE, PasswordHash TEXT NOT NULL, Email TEXT NOT NULL, RoleId INTEGER NOT NULL REFERENCES Roles(Id));
CREATE INDEX IX_Products_TypeId ON Products(TypeId);
CREATE INDEX IX_Orders_UserId ON Orders(UserId);
COMMIT;
PRAGMA foreign_keys=ON;
PRAGMA foreign_key_check;
